function printWindow(title,html){const w=window.open('','_blank','width=1000,height=760');if(!w){toast('اسمح بالنوافذ المنبثقة للطباعة');return}w.document.write(`<!doctype html><html dir="rtl"><head><meta charset="utf-8"><title>${esc(title)}</title><style>@page{size:A4;margin:10mm}*{box-sizing:border-box}body{font-family:Arial,Tahoma;margin:0}.sheet{display:grid;grid-template-columns:repeat(2,1fr);gap:8mm}.student-card-print{border:1px solid #ccd5dd;border-radius:16px;padding:14px;height:78mm;display:flex;flex-direction:column;justify-content:space-between;page-break-inside:avoid}.book-label{border:1px solid #bbb;border-radius:10px;padding:9px;height:43mm;page-break-inside:avoid}.top{display:flex;gap:10px;align-items:center}.plogo{width:46px;height:46px;object-fit:contain}.mark{width:44px;height:44px;border-radius:12px;background:#12384a;color:white;display:grid;place-items:center;font-weight:bold}.school,.small{font-size:11px;color:#666}.name{font-size:18px;font-weight:800;margin:10px 0 4px}.meta{font-size:12px;color:#555}.barcode{height:18mm;margin-top:8px}.barcode svg{width:100%;height:100%}.code{text-align:center;font:700 12px monospace;letter-spacing:1px}.book-label .name{font-size:14px}.book-label .barcode{height:13mm}@media print{button{display:none}}</style></head><body><div class="sheet">${html}</div><script>window.onload=()=>setTimeout(()=>window.print(),250)<\/script></body></html>`);w.document.close()}
function studentCardHTML(s){return `<div class="student-card-print"><div><div class="top">${state.config.logo?`<img class="plogo" src="${state.config.logo}">`:'<div class="mark">م</div>'}<div><b>${esc(state.config.schoolName)}</b><div class="school">${esc(state.config.siteName)}</div></div></div><div class="name">${esc(s.name)}</div><div class="meta">الصف: ${esc(s.grade)} — الشعبة: ${esc(s.section)}</div></div><div><div class="barcode">${barcodeSVG(s.code)}</div><div class="code">${esc(s.code)}</div></div></div>`}
